public sealed class JwtOptions
{
    public const string SectionName = "Jwt";

    [Required(ErrorMessage = "Jwt:Issuer is required")]
    [Url]
    public string Issuer { get; set; } = "";

    [Required]
    [MinLength(32, ErrorMessage = "SigningKey must be at least 32 characters")]
    public string SigningKey { get; set; } = "";

    [Range(1, 1440)]
    public int ExpiryMinutes { get; set; } = 60;
}

public sealed class JwtOptionsValidator : IValidateOptions<JwtOptions>
{
    public ValidateOptionsResult Validate(string? name, JwtOptions options)
    {
        if (options.ExpiryMinutes > 60 && string.IsNullOrEmpty(options.RefreshTokenSecret))
            return ValidateOptionsResult.Fail(
                "RefreshTokenSecret required when ExpiryMinutes > 60");

        if (options.SigningKey.Contains("dev-placeholder", StringComparison.OrdinalIgnoreCase)
            && !IsDevelopment())
            return ValidateOptionsResult.Fail("Dev signing key cannot be used in production");

        return ValidateOptionsResult.Success;
    }
}

builder.Services.AddSingleton<IValidateOptions<JwtOptions>, JwtOptionsValidator>();

